#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;
const int MODULUS=1e9+7;
typedef long long LLType;
LLType num;
int len, baseVal, total, index, digitArr[110];
void update(int &x, int y, int m) {
    x += y; if (x >= m) x -= m;
}
struct MatrixType {
    int matrix[35][35];
    MatrixType() { memset(matrix, 0, sizeof(matrix)); }
    MatrixType operator*(const MatrixType &other) const {
        MatrixType result;
        for (int k=0; k<=baseVal; k++)
            for (int i=0; i<=baseVal; i++)
                if (matrix[i][k])
                    for (int j=0; j<=baseVal; j++)
                        if (other.matrix[k][j])
                            result.matrix[i][j] = (1LL * matrix[i][k] * other.matrix[k][j] + result.matrix[i][j]) % MODULUS;
        return result;
    }
} finalAnswer, sMatrices[75][35], prefixMatrices[75][35], suffixMatrices[75][35];

void extractDigits(LLType number) {
    LLType temp=number;
    len=0;
    while (temp) {
        digitArr[++len]=temp%baseVal;
        temp/=baseVal;
    }
    reverse(digitArr+1, digitArr+len+1);
}

int main() {
    scanf("%lld%d", &num, &baseVal);
    extractDigits(num);
    for (int i=0; i<baseVal; i++) {
        for (int j=0; j<=baseVal; j++) sMatrices[0][i].matrix[j][j]=1;
        for (int j=0; j<=baseVal; j++) sMatrices[0][i].matrix[i][j]=1;
    }
    for (int i=1; i<=len; i++) {
        prefixMatrices[i-1][0]=sMatrices[i-1][0];
        suffixMatrices[i-1][baseVal-1]=sMatrices[i-1][baseVal-1];
        for (int j=1; j<baseVal; j++) prefixMatrices[i-1][j]=prefixMatrices[i-1][j-1]*sMatrices[i-1][j];
        for (int j=baseVal-2; j>=0; j--) suffixMatrices[i-1][j]=sMatrices[i-1][j]*suffixMatrices[i-1][j+1];
        for (int j=0; j<baseVal; j++)
            if (j) sMatrices[i][j]=suffixMatrices[i-1][j]*prefixMatrices[i-1][j-1];
            else sMatrices[i][j]=suffixMatrices[i-1][j];
    }
    for (int i=0; i<=baseVal; i++)
        for (int j=0; j<=baseVal; j++)
            finalAnswer.matrix[i][j]=(i==j);
    index=0;
    for (int i=1; i<=len; i++) {
        if (digitArr[i]) {
            if (index+digitArr[i]-1>=baseVal) {
                for (int j=index; j<baseVal; j++) finalAnswer=finalAnswer*sMatrices[len - i][j];
                for (int j=0; j<=(index+digitArr[i]-1)-baseVal; j++) finalAnswer=finalAnswer*sMatrices[len - i][j];
            } else {
                for (int j=index; j<=index+digitArr[i]-1; j++) finalAnswer=finalAnswer*sMatrices[len - i][j];
            }
            update(index, digitArr[i], baseVal);
        }
    }
    for (int i=0; i<=baseVal; i++) update(total, finalAnswer.matrix[i][baseVal], MODULUS);
    printf("%d\n", total);
    return 0;
}
